/// The boot sequence: named steps, in the order they must happen.
///
/// `_load()` was 304 lines of sequential procedure — parallelised, but not
/// extracted. You could not say where one phase ended and the next began without
/// reading the whole method, and the only record of the order was the phase log it
/// printed as it went.
///
/// So the order is a list now, each entry a named step, and the log is generated by
/// the steps as they run: `[Sonarar] boot NN% label (+Nms)`, the same line as
/// before, so a boot that behaves differently is visible by diffing two logs.
///
/// A step returns false to stop the sequence. That is what a disposed shell does
/// halfway through boot: the steps after it must not run, and the log must stop
/// where the work stopped.
library;

import 'package:flutter/foundation.dart' show debugPrint;

/// One step of boot. False means "nothing after this can run".
typedef BootStep = Future<bool> Function(Bootstrapper boot);

class Bootstrapper {
  Bootstrapper({required this.onPhase});

  /// Called on every phase boundary, so the shell can repaint its boot screen.
  /// The log itself belongs here, not to the caller.
  final void Function(double progress) onPhase;

  /// How long each label took, keyed by label. Sub-steps a phase reports are timed
  /// the same way — the gap is always "since the previous line".
  final Map<String, int> costs = {};

  /// Every label in the order it was printed.
  final List<String> labels = [];

  DateTime? _last;

  bool _stopped = false;

  /// True when a step said to stop. The log ends where the work ended.
  bool get stopped => _stopped;

  Future<void> run(List<BootStep> steps) async {
    _stopped = false;
    for (final step in steps) {
      final go = await step(this);
      if (!go) {
        _stopped = true;
        return;
      }
    }
  }

  /// Prints one phase boundary, and times it against the previous one.
  void note(double progress, String label) {
    final now = DateTime.now();
    final since = _last == null ? null : now.difference(_last!).inMilliseconds;
    _last = now;
    if (since != null) costs[label] = since;
    labels.add(label);

    onPhase(progress);
    debugPrint('[Sonarar] boot ${(progress * 100).round()}% $label'
        '${since == null ? '' : ' (+${since}ms)'}');

    if (progress >= 1.0) {
      final ranked = costs.entries.toList()
        ..sort((a, b) => b.value.compareTo(a.value));
      debugPrint('[Sonarar] boot TOTAL '
          '${ranked.fold<int>(0, (sum, e) => sum + e.value)}ms — slowest: '
          '${ranked.take(3).map((e) => '${e.key}=${e.value}ms').join(', ')}');
    }
  }
}
